47	// Transcribe transcribes an audio file using an instance AI provider.
48	func (s *APIV1Service) Transcribe(ctx context.Context, request *v1pb.TranscribeRequest) (*v1pb.TranscribeResponse, error) {
49		user, err := s.fetchCurrentUser(ctx)
50		if err != nil {
51			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
52		}
53		if user == nil {
54			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
55		}
56	
57		if request.Audio == nil {
58			return nil, status.Errorf(codes.InvalidArgument, "audio is required")
59		}
60		if request.Audio.GetUri() != "" {
61			return nil, status.Errorf(codes.InvalidArgument, "audio uri is not supported")
62		}
63		content := request.Audio.GetContent()
64		if len(content) == 0 {
65			return nil, status.Errorf(codes.InvalidArgument, "audio content is required")
66		}
67		if len(content) > maxTranscriptionAudioSizeBytes {
68			return nil, status.Errorf(codes.InvalidArgument, "audio file is too large; maximum size is 25 MiB")
69		}
70		filename := strings.TrimSpace(request.Audio.GetFilename())
71		if len(filename) > maxTranscriptionFilenameLength {
72			return nil, status.Errorf(codes.InvalidArgument, "filename is too long; maximum length is %d characters", maxTranscriptionFilenameLength)
73		}
74		contentType := strings.TrimSpace(request.Audio.GetContentType())
75		if contentType == "" {
76			contentType = http.DetectContentType(content)
77		}
78		if !isSupportedTranscriptionContentType(contentType) {
79			return nil, status.Errorf(codes.InvalidArgument, "audio content type %q is not supported", contentType)
80		}
81	
82		aiSetting, err := s.Store.GetInstanceAISetting(ctx)
83		if err != nil {
84			return nil, status.Errorf(codes.Internal, "failed to get AI setting: %v", err)
85		}
86		persisted := aiSetting.GetTranscription()
87	
88		providerID := persisted.GetProviderId()
89		if providerID == "" {
90			return nil, status.Errorf(codes.FailedPrecondition, "transcription is not configured")
91		}
92	
93		provider, err := s.resolveAIProvider(aiSetting, providerID)
94		if err != nil {
95			return nil, err
96		}
97	
98		model := persisted.GetModel()
99		if model == "" {
100			defaultModel, err := ai.DefaultTranscriptionModel(provider.Type)
101			if err != nil {
102				return nil, status.Errorf(codes.InvalidArgument, "%v", err)
103			}
104			model = defaultModel
105		}
106	
107		var text string
108		switch provider.Type {
109		case ai.ProviderOpenAI:
110			text, err = s.transcribeViaSTT(ctx, provider, persisted, model, content, filename, contentType)
111		case ai.ProviderGemini:
112			text, err = s.transcribeViaAudioLLM(ctx, provider, persisted, model, content, contentType)
113		default:
114			return nil, status.Errorf(codes.FailedPrecondition,
115				"provider type %q is not supported for transcription", provider.Type)
116		}
117		if err != nil {
118			return nil, status.Errorf(codes.Internal, "failed to transcribe audio: %v", err)
119		}
120		return &v1pb.TranscribeResponse{Text: text}, nil
121	}
122	
123	func (*APIV1Service) transcribeViaSTT(
124		ctx context.Context,
125		provider ai.ProviderConfig,
126		persisted *storepb.TranscriptionConfig,
127		model string,
128		content []byte,
129		filename string,
130		contentType string,
131	) (string, error) {
132		transcriber, err := sttopenai.New(provider, stt.ApplyOptions(nil))
133		if err != nil {
134			return "", errors.Wrap(err, "failed to create STT transcriber")
135		}
136		resp, err := transcriber.Transcribe(ctx, stt.Request{
137			Audio:       bytes.NewReader(content),
138			Size:        int64(len(content)),
139			Filename:    filename,
140			ContentType: contentType,
141			Model:       model,
142			Prompt:      persisted.GetPrompt(),
143			Language:    persisted.GetLanguage(),
144		})
145		if err != nil {
146			return "", err
147		}
148		return resp.Text, nil
149	}
150	
151	func (*APIV1Service) transcribeViaAudioLLM(
152		ctx context.Context,
153		provider ai.ProviderConfig,
154		persisted *storepb.TranscriptionConfig,
155		model string,
156		content []byte,
157		contentType string,
158	) (string, error) {
159		m, err := audiollmgemini.New(provider, audiollm.ApplyOptions(nil))
160		if err != nil {
161			return "", errors.Wrap(err, "failed to create audio LLM")
162		}
163		resp, err := m.GenerateFromAudio(ctx, audiollm.Request{
164			Audio:        bytes.NewReader(content),
165			Size:         int64(len(content)),
166			ContentType:  contentType,
167			Model:        model,
168			Instructions: buildTranscriptionInstructions(persisted.GetPrompt(), persisted.GetLanguage()),
169		})
170		if err != nil {
171			return "", err
172		}
173		if resp.FinishReason != audiollm.FinishStop {
174			return "", errors.Errorf("transcription incomplete (finish reason: %s)", resp.FinishReason)
175		}
176		if strings.TrimSpace(resp.Text) == "" {
177			return "", errors.New("transcription response did not include text")
178		}
179		return resp.Text, nil
180	}
181	
182	func buildTranscriptionInstructions(prompt, language string) string {
183		parts := []string{
184			"Transcribe the audio accurately. Return only the transcript text. " +
185				"Do not summarize, explain, or add content that is not spoken.",
186		}
187		if language = strings.TrimSpace(language); language != "" {
188			parts = append(parts, "The input language is "+language+".")
189		}
190		if prompt = strings.TrimSpace(prompt); prompt != "" {
191			parts = append(parts, "Context and spelling hints:\n"+prompt)
192		}
193		return strings.Join(parts, "\n\n")
194	}
195	
196	func (*APIV1Service) resolveAIProvider(setting *storepb.InstanceAISetting, providerID string) (ai.ProviderConfig, error) {
197		providers := make([]ai.ProviderConfig, 0, len(setting.GetProviders()))
198		for _, provider := range setting.GetProviders() {
199			if provider == nil {
200				continue
201			}
202			providers = append(providers, convertAIProviderConfigFromStore(provider))
203		}
204	
205		provider, err := ai.FindProvider(providers, providerID)
206		if err != nil {
207			return ai.ProviderConfig{}, status.Errorf(codes.FailedPrecondition, "transcription provider is not configured")
208		}
209		return *provider, nil
210	}
211	
212	func convertAIProviderConfigFromStore(provider *storepb.AIProviderConfig) ai.ProviderConfig {
213		return ai.ProviderConfig{
214			ID:       provider.GetId(),
215			Title:    provider.GetTitle(),
216			Type:     convertAIProviderTypeFromStore(provider.GetType()),
217			Endpoint: provider.GetEndpoint(),
218			APIKey:   provider.GetApiKey(),
219		}
220	}
221	
222	func convertAIProviderTypeFromStore(providerType storepb.AIProviderType) ai.ProviderType {
223		switch providerType {
224		case storepb.AIProviderType_OPENAI:
225			return ai.ProviderOpenAI
226		case storepb.AIProviderType_GEMINI:
227			return ai.ProviderGemini
228		default:
229			return ""
230		}
231	}
232	
233	func isSupportedTranscriptionContentType(contentType string) bool {
234		mediaType, _, err := mime.ParseMediaType(strings.TrimSpace(contentType))
235		if err != nil {
236			return false
237		}
238		mediaType = strings.ToLower(mediaType)
239		return supportedTranscriptionContentTypes[mediaType]
240	}
